// === Tab: mySketch ===
PVector [] points;

function setup() {
  createCanvas(320, 480);
  points = new Array(700);
  for (i = 0; i < points.length; i++) {
    points[i] = new PVector();
  }

  // stroke(255, 150);
  // strokeWeight(2);

	noStroke();
	fill(255,100);
}

let ease = .03;

function draw() {
  background(0);

  translate(width/2, height/2);

  let a = 0;
  let mouse = map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, 0, PI);
	let reducer = .5;					    // <-- change this

  for (i = 0; i < points.length; i++) {
    let remain = sin((a + frameCount * .008 % TWO_PI) * reducer + mouse);
    let range = remain * 100;
    let r = map(noise(a + frameCount*.03), 0, 1, -range, range) + 100;

    let targetX = cos(a) * r;
    let targetY = sin(a) * r;

    let dx = targetX - points[i].x;
    let dy = targetY - points[i].y;

    points[i].x += dx * ease;
    points[i].y += dy * ease;
    a += .1;
  }

  for (i = 0; i < points.length; i++) {
    ellipse(points[i].x, points[i].y, 4, 4);
  }
}

